const templateKey = clean(query.template_key);
const signatureTemplateKey = clean(query.signature_template_key) || clean(settings.email_signature_template_key) || 'signature';
const returnUrl = clean(query.return_url) || (n8nBaseUrl + '/webhook/case-tracking?view=dashboard');
