  json: {
    case_id: caseId,
    mode,
    reply_to_case_email_id: replyToCaseEmailId,
    reply_quote_mode: allowedQuoteModes.has(requestedQuoteMode) ? requestedQuoteMode : '',
    template_key: templateKey,
    signature_template_key: signatureTemplateKey,
    to: clean(query.to),
    cc: clean(query.cc),
    return_url: returnUrl,
