  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n\n')
  .replace(/<\/div>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/\n{3,}/g, '\n\n')
  .trim();
const htmlFromText = (value) => escapeHtml(value).split('\n').map((line) => line ? '<div>' + line + '</div>' : '<div><br></div>').join('');
const applyTokens = (value) => {
  let rendered = String(value ?? '');
  const tokenMap = {
    '{{case_title}}': clean(caseRow.title),
    '{{case_status}}': clean(caseRow.status),
    '{{case_priority}}': clean(caseRow.priority),
    '{{contact_name}}': clean(caseRow.contact_name),
    '{{contact_email}}': clean(caseRow.contact_email),
    '{{contact_phone}}': clean(caseRow.contact_phone),
    '{{today}}': new Date().toLocaleDateString('en-GB'),
  };
  for (const [token, replacement] of Object.entries(tokenMap)) {
    rendered = rendered.split(token).join(replacement);
  }
  return rendered.trim();
};
const hasHtmlContent = Boolean(clean(context.html_template) || signatureTemplates.some((template) => clean(template.html_template)));
const emailType = hasHtmlContent ? 'html' : 'text';
const normalizeReplySubject = (value) => {
  const base = clean(value).replace(/^((re|fw|fwd)\s*:\s*)+/i, '').trim();
  return base ? 'Re: ' + base : 'Re: Update from Avondale Tennis Club';
};
const normalizeForwardSubject = (value) => {
  const base = clean(value).replace(/^((re|fw|fwd)\s*:\s*)+/i, '').trim();
  return base ? 'Fwd: ' + base : 'Fwd: Update from Avondale Tennis Club';
};
const extractEmailAddress = (value) => {
  const text = clean(value);
  if (!text) return '';
  const bracketMatch = text.match(/<\s*([^<>\s]+@[^<>\s]+)\s*>/);
  if (bracketMatch) return clean(bracketMatch[1]);
  const emailMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return emailMatch ? clean(emailMatch[0]) : '';
};
const addressEntries = (value) => String(value ?? '')
  .split(/,(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)/)
  .map((entry) => entry.trim())
  .filter(Boolean)
  .map((entry) => ({ raw: entry, email: extractEmailAddress(entry).toLowerCase() }))
  .filter((entry) => entry.email);
const uniqueAddresses = (values, excludedEmails = []) => {
  const excluded = new Set(excludedEmails.map((email) => clean(email).toLowerCase()).filter(Boolean));
  const seen = new Set();
  const result = [];
  for (const value of values) {
    for (const entry of addressEntries(value)) {
      if (!entry.email || excluded.has(entry.email) || seen.has(entry.email)) continue;
      seen.add(entry.email);
      result.push(entry.raw);
    }
  }
  return result.join(', ');
};
const internalEmails = [input.reply_to, 'members.avondaleltc@gmail.com'].map((email) => extractEmailAddress(email).toLowerCase()).filter(Boolean);
const pickReplyRecipient = () => {
  const explicitRecipient = clean(input.to);
  if (explicitRecipient) return explicitRecipient;
  const candidates = clean(parentEmailRow.direction) === 'outgoing'
    ? [parentRecipients.to, parentRecipients.actual_to, parentRecipients.from, parentRecipients.reply_to]
    : [parentRecipients.reply_to, parentRecipients.from, parentRecipients.to, parentRecipients.actual_to];
  return uniqueAddresses(candidates, internalEmails) || extractEmailAddress(caseRow.contact_email) || clean(caseRow.contact_email);
};
const pickReplyAllRecipients = () => {
  const primary = pickReplyRecipient();
  return primary;
};
const pickReplyAllCc = () => {
  if (clean(input.cc)) return clean(input.cc);
  return uniqueAddresses([parentRecipients.to, parentRecipients.cc], [pickReplyRecipient(), ...internalEmails]);
};
const formatDisplayAddress = (recipients, row) => {
  const candidate = clean(row?.direction) === 'outgoing'
    ? (recipients.from || input.reply_to || 'members.avondaleltc@gmail.com')
    : (recipients.reply_to || recipients.from || row?.created_by || 'Unknown sender');
  return clean(candidate) || 'Unknown sender';
};
const formatQuoteDate = (row) => {
  const value = clean(row?.sent_at) || clean(row?.created_at);
  const parsed = value ? new Date(value) : null;
  if (!parsed || Number.isNaN(parsed.getTime())) return 'an earlier message';
  return parsed.toLocaleString('en-GB', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
};
const stripTrackingPixels = (value) => String(value || '')
  .replace(/<img\b(?=[^>]*\bwidth=["']?1["']?)(?=[^>]*\bheight=["']?1["']?)[^>]*>/gi, '')
  .replace(/<img\b[^>]*6f3d9e58-5f0c-4f3e-b29c-1d6c8ef9d4a1\.gif[^>]*>/gi, '');
