const messageBodyText = (row) => clean(row?.body_text) || stripHtml(row?.body_html);
const buildHtmlQuote = (rows) => rows.map((row) => {
  const recipients = parseRecipients(row.recipients);
  const author = formatDisplayAddress(recipients, row);
  const attr = 'On ' + formatQuoteDate(row) + ', ' + author + ' wrote:';
  return '<div class="av-reply-quote gmail_quote" style="margin-top:16px"><div class="gmail_attr" style="font-size:13px;color:#555;margin-bottom:8px">' + escapeHtml(attr) + '</div><blockquote class="gmail_quote" style="margin:0 0 0 .8ex;border-left:1px solid #ccc;padding-left:1ex;color:#222">' + messageBodyHtml(row) + '</blockquote></div>';
}).join('');
const buildTextQuote = (rows) => rows.map((row) => {
  const recipients = parseRecipients(row.recipients);
  const author = formatDisplayAddress(recipients, row);
  const body = messageBodyText(row).split('\n').map((line) => '> ' + line).join('\n');
  return 'On ' + formatQuoteDate(row) + ', ' + author + ' wrote:\n' + body;
}).join('\n\n');
const buildForwardHtml = (row) => {
  const recipients = parseRecipients(row.recipients);
  const headerRows = [
    ['From', recipients.from],
    ['Date', formatQuoteDate(row)],
    ['Subject', row.subject],
    ['To', recipients.to],
    ['Cc', recipients.cc],
  ].filter((entry) => clean(entry[1]));
  const headers = headerRows.map(([label, value]) => '<div><b>' + escapeHtml(label) + ':</b> ' + escapeHtml(value) + '</div>').join('');
  return '<div class="av-forwarded-message" style="margin-top:16px"><div style="font-weight:600;margin-bottom:8px">---------- Forwarded message ---------</div>' + headers + '<br>' + messageBodyHtml(row) + '</div>';
};
const buildForwardText = (row) => {
  const recipients = parseRecipients(row.recipients);
  const headerRows = [
    ['From', recipients.from],
    ['Date', formatQuoteDate(row)],
    ['Subject', row.subject],
    ['To', recipients.to],
    ['Cc', recipients.cc],
  ].filter((entry) => clean(entry[1]));
  return ['---------- Forwarded message ---------', ...headerRows.map(([label, value]) => label + ': ' + value), '', messageBodyText(row)].join('\n');
};
const parentIndex = threadMessageRows.findIndex((row) => clean(row.id) === clean(parentEmailRow.id));
const threadRowsForQuote = parentIndex >= 0 ? threadMessageRows.slice(0, parentIndex + 1) : threadMessageRows;
const previousRowsForQuote = clean(parentEmailRow.id) ? [parentEmailRow] : [];
const quoteBlocks = {
  none: { html: '', text: '' },
  previous: { html: buildHtmlQuote(previousRowsForQuote), text: buildTextQuote(previousRowsForQuote) },
  thread: { html: buildHtmlQuote(threadRowsForQuote), text: buildTextQuote(threadRowsForQuote) },
  forward: { html: buildForwardHtml(parentEmailRow), text: buildForwardText(parentEmailRow) },
};
const requestedReplyQuoteMode = clean(input.reply_quote_mode);
const composeMode = clean(input.mode) || 'new';
const replyQuoteMode = ['reply', 'reply_all'].includes(composeMode)
  ? (['none', 'previous', 'thread'].includes(requestedReplyQuoteMode) ? requestedReplyQuoteMode : 'previous')
  : (composeMode === 'forward' ? 'forward' : 'none');
const renderedSubject = composeMode === 'forward'
  ? normalizeForwardSubject(clean(parentEmailRow.subject) || clean(context.subject_template) || clean(caseRow.title) || 'Update from Avondale Tennis Club')
  : (['reply', 'reply_all'].includes(composeMode)
